{
  "description": "The creature is shown in right-facing side profile standing on four legs against a plain light background. It has the overall shape, dense shaggy brown fur, and head of a bear, but its dorsal surface from the back of the neck to the tip of the rear is covered by a glossy dark brown segmented exoskeleton with overlapping transverse plates. A single large glossy dark curved horn projects from the center of the forehead. The furry underparts, sides of the neck, and all four limbs contrast with the shiny armored covering, which extends down the sides with rows of oval openings and tapers to a narrow pointed tip at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with dense fur, lighter tan around the muzzle, a dark nose at the tip of an elongated snout, small dark eyes, and a closed mouth",
      "where": "at the anterior end of the body, in front of the armored neck"
    },
    {
      "part": "horns",
      "looks_like": "a single large glossy blackish-brown horn curving upward and backward then forward to a sharp tip, with a small tooth-like notch on the inner curve near the tip",
      "where": "arising centrally from the forehead on top of the head between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in brown fur",
      "where": "on top of the head behind the horn, one on each side"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar, shaggy-haired brown legs with dense long fur",
      "where": "two forelegs under the chest and two hindlegs under the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with visible pale curved claws on each toe",
      "where": "at the distal ends of the legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short narrow pointed tail made of small overlapping glossy dark segments tapering to a sharp tip",
      "where": "at the posterior end of the body extending beyond the hindquarters from the end of the dorsal armor"
    },
    {
      "part": "shell",
      "looks_like": "a large glossy dark brown carapace of overlapping transverse plates separated by thin tan lines, with a larger smooth shoulder plate and a shiny reflective surface",
      "where": "covering the entire dorsal surface from the back of the neck over the back to the tail"
    },
    {
      "part": "plates",
      "looks_like": "smaller segmented glossy plates wrapping around the neck and lower sides, with a row of oval openings with light rims along the flank",
      "where": "around the neck, throat, and along the sides of the body beneath the main dorsal shell"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
